<?php
defined('WB_PATH') or die('No direct access');
function wbce_silktide_settings(): array {$raw=Settings::get('cookie_banner_silktide','');$data=json_decode((string)$raw,true);return array_merge(array('prompt_position'=>'bottomRight','icon_position'=>'bottomLeft','backdrop'=>'0','auto_show'=>'1','namespace'=>'wbce_silktide','event_name'=>'stcm_consent_update','debug'=>'0','primary_color'=>'#1769aa','background_color'=>'#ffffff','text_color'=>'#1d2327','icon_color'=>'#1769aa','icon_background'=>'#ffffff','prompt_description'=>'Wir verwenden Cookies und ähnliche Technologien.','accept'=>'Alle akzeptieren','reject'=>'Nur optionale ablehnen','preferences'=>'Einstellungen','preferences_title'=>'Datenschutzeinstellungen','preferences_description'=>'Wählen Sie, welche optionalen Dienste verwendet werden dürfen.','save'=>'Speichern','show_branding'=>'1','show_revoke'=>'1'),is_array($data)?$data:array());}
function wbce_silktide_value(string $name): string {$s=wbce_silktide_settings();return htmlspecialchars((string)($s[$name]??''),ENT_QUOTES,'UTF-8');}
function wbce_silktide_select(string $name,array $options): string {$current=htmlspecialchars_decode(wbce_silktide_value($name));$html='<select name="cookie_silktide_'.$name.'">';foreach($options as $value=>$label)$html.='<option value="'.htmlspecialchars($value,ENT_QUOTES,'UTF-8').'"'.($current===$value?' selected':'').'>'.htmlspecialchars($label,ENT_QUOTES,'UTF-8').'</option>';return $html.'</select>';}
if(function_exists('wbce_add_filter'))wbce_add_filter('cookie_banner.providers',static function($items){
    $items['silktide']=array('name'=>'Silktide Consent Manager','description'=>'Lokal gehostet mit Kategorien, Script-Injektion und Consent Mode.','render'=>static function($categories,$central){
        $s=wbce_silktide_settings();$color=static function($value){return preg_match('/^#[0-9a-f]{6}$/i',(string)$value)?$value:'#1769aa';};$types=array();foreach($categories as $id=>$category){$scripts=array();foreach((array)($category['scripts']??array())as $url)$scripts[]=array('url'=>$url,'load'=>'async');$type=array('id'=>$id,'label'=>$category['name'],'description'=>$category['description'],'required'=>(bool)$category['required'],'defaultValue'=>(bool)$category['required'],'scripts'=>$scripts);if($id==='analytics')$type['gtag']='analytics_storage';if($id==='marketing')$type['gtag']=array('ad_storage','ad_user_data','ad_personalization');$types[]=$type;}
        $config=array('consentTypes'=>$types,'eventName'=>$s['event_name'],'namespace'=>$s['namespace'],'debug'=>!empty($s['debug']),'autoShow'=>!empty($s['auto_show']),'prompt'=>array('position'=>$s['prompt_position']),'icon'=>array('position'=>$s['icon_position']),'backdrop'=>array('show'=>!empty($s['backdrop'])),'text'=>array('prompt'=>array('description'=>$s['prompt_description'],'acceptAllButtonText'=>$s['accept'],'rejectNonEssentialButtonText'=>$s['reject'],'preferencesButtonText'=>$s['preferences']),'preferences'=>array('title'=>$s['preferences_title'],'description'=>$s['preferences_description'],'saveButtonText'=>$s['save'])));$branding=empty($s['show_branding'])?'<style>#stcm-banner .stcm-logo,#stcm-modal .stcm-credit-link{display:none!important}</style>':'';$revoke=empty($s['show_revoke'])?'<style>#stcm-icon{display:none!important}</style>':'';$css='#stcm-wrapper{--primaryColor:'.$color($s['primary_color']).';--backgroundColor:'.$color($s['background_color']).';--textColor:'.$color($s['text_color']).';--iconColor:'.$color($s['icon_color']).';--iconBackgroundColor:'.$color($s['icon_background']).';}';$json=json_encode($config,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);$url=WB_URL.'/modules/cookie_banner_silktide/assets/';return $branding.$revoke.'<link rel="stylesheet" href="'.$url.'silktide-consent-manager.css"><style>'.$css.'</style><script src="'.$url.'silktide-consent-manager.js" defer></script><script>window.addEventListener("DOMContentLoaded",function(){if(window.silktideConsentManager){var c='.$json.';c.consentTypes.forEach(function(type){type.onAccept=function(){if(window.WbceCookieIntegrations)window.WbceCookieIntegrations.load(type.id);};});window.silktideConsentManager.init(c);window.setTimeout(function(){var m=window.silktideConsentManager.getInstance();if(!m||!window.WbceCookieIntegrations)return;c.consentTypes.forEach(function(type){if(m.getConsentChoice(type.id))window.WbceCookieIntegrations.load(type.id);});},0);}});</script>';});return $items;
});
if(function_exists('wbce_add_filter'))wbce_add_filter('cookie_banner.settings.sections',static function($sections){
$v='wbce_silktide_value';$sections[]='<section class="cookie-provider-main-frame cookie-provider-settings" data-provider="silktide"><div class="cookie-provider-main-frame__header"><i class="fa fa-shield" aria-hidden="true"></i><h3>Silktide Consent Manager</h3></div><div class="cookie-banner-grid"><label>Position'.wbce_silktide_select('prompt_position',array('center'=>'Zentriert','bottomLeft'=>'Unten links','bottomCenter'=>'Unten mittig','bottomRight'=>'Unten rechts')).'</label><label>Icon-Position'.wbce_silktide_select('icon_position',array('bottomLeft'=>'Unten links','bottomRight'=>'Unten rechts')).'</label><label>Lokaler Speicherbereich<input name="cookie_silktide_namespace" value="'.$v('namespace').'"></label><label>GTM-Ereignis<input name="cookie_silktide_event_name" value="'.$v('event_name').'"></label><label>Primärfarbe<input type="color" name="cookie_silktide_primary_color" value="'.$v('primary_color').'"></label><label>Hintergrund<input type="color" name="cookie_silktide_background_color" value="'.$v('background_color').'"></label><label>Textfarbe<input type="color" name="cookie_silktide_text_color" value="'.$v('text_color').'"></label><label>Iconfarbe<input type="color" name="cookie_silktide_icon_color" value="'.$v('icon_color').'"></label><label>Icon-Hintergrund<input type="color" name="cookie_silktide_icon_background" value="'.$v('icon_background').'"></label><label class="full">Hinweis<textarea name="cookie_silktide_prompt_description" rows="3">'.$v('prompt_description').'</textarea></label><label>Akzeptieren<input name="cookie_silktide_accept" value="'.$v('accept').'"></label><label>Ablehnen<input name="cookie_silktide_reject" value="'.$v('reject').'"></label><label>Einstellungen<input name="cookie_silktide_preferences" value="'.$v('preferences').'"></label><label>Dialogtitel<input name="cookie_silktide_preferences_title" value="'.$v('preferences_title').'"></label><label class="full">Dialogtext<textarea name="cookie_silktide_preferences_description" rows="2">'.$v('preferences_description').'</textarea></label><label>Speichern<input name="cookie_silktide_save" value="'.$v('save').'"></label></div><div class="cookie-checkboxes"><label><input type="checkbox" name="cookie_silktide_show_revoke" value="1"'.(wbce_silktide_value('show_revoke')==='1'?' checked':'').'> Widerruf anzeigen</label><label><input type="checkbox" name="cookie_silktide_show_branding" value="1"'.(wbce_silktide_value('show_branding')==='1'?' checked':'').'> Anbieterkennzeichnung anzeigen</label><label><input type="checkbox" name="cookie_silktide_backdrop" value="1"'.(wbce_silktide_value('backdrop')==='1'?' checked':'').'> Hintergrundüberlagerung</label><label><input type="checkbox" name="cookie_silktide_auto_show" value="1"'.(wbce_silktide_value('auto_show')==='1'?' checked':'').'> Bei Erstbesuch anzeigen</label><label><input type="checkbox" name="cookie_silktide_debug" value="1"'.(wbce_silktide_value('debug')==='1'?' checked':'').'> Diagnoseausgaben</label></div></section>';return $sections;
});
if(function_exists('wbce_add_action'))wbce_add_action('cookie_banner.settings.save',static function($post){$keys=array('prompt_position','icon_position','namespace','event_name','primary_color','background_color','text_color','icon_color','icon_background','prompt_description','accept','reject','preferences','preferences_title','preferences_description','save');$data=array();foreach($keys as $key)$data[$key]=trim((string)($post['cookie_silktide_'.$key]??''));foreach(array('show_revoke','show_branding','backdrop','auto_show','debug')as$key)$data[$key]=empty($post['cookie_silktide_'.$key])?'0':'1';Settings::set('cookie_banner_silktide',json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));});
